const app=document.getElementById('app');let cache={};let toastTimer;let session={accessToken:null,user:null};let viewEpoch=0;
let leafletPromise;
function ensureLeaflet(){
 if(window.L)return Promise.resolve(true);
 if(leafletPromise)return leafletPromise;
 leafletPromise=new Promise(resolve=>{
  const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.append(css);
  const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
  let settled=false;const finish=ok=>{if(settled)return;settled=true;clearTimeout(timeout);resolve(ok);if(ok&&['fields','satellite'].includes(location.hash.slice(2)))render()};
  const timeout=setTimeout(()=>finish(false),5000);script.onload=()=>finish(true);script.onerror=()=>finish(false);document.head.append(script);
 });
 return leafletPromise;
}
